calls = 0
def fib(n):
    global calls
    calls += 1
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)
fib(20)
print(calls)  # 21891 (fib(10) makes 177)
Each call makes two more, so the call count multiplies as n grows: exponential, written O(2^n).

def linear_search(items, target):
    for i in range(len(items)):
        if items[i] == target:
            return i
    return -1
print(linear_search([4, 8, 15, 16], 15), linear_search([4, 8], 7))  # 2 -1
The return -1 comes after the loop: only when every item has been checked do we know the target is missing.

