def search_sorted(items, target):
    for i in range(len(items)):
        if items[i] == target:
            return i
        if items[i] > target:
            return -1   # everything after is bigger too
    return -1
print(search_sorted([2, 5, 9, 14], 6))  # -1 after 3 checks
Sorting lets a missing item be detected early, but the worst case is still n checks: still O(n).

def binary_search(items, target):
    low, high = 0, len(items) - 1
    while low <= high:
        mid = (low + high) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1
print(binary_search([3, 8, 12, 19, 25, 31, 40], 25))  # 4
mid + 1 and mid - 1: the middle has been checked, so it is excluded from the next range.

def first_index(items, target):
    low, high = 0, len(items) - 1
    answer = -1
    while low <= high:
        mid = (low + high) // 2
        if items[mid] < target:
            low = mid + 1
        else:
            if items[mid] == target:
                answer = mid
            high = mid - 1
    return answer
print(first_index([1, 2, 2, 2, 5], 2))  # 1
Plain binary search returns whichever 2 it hits first (here index 2). Remembering the match and continuing left finds the first one.

def contains(items, target):
    if items == []:
        return False
    mid = len(items) // 2
    if items[mid] == target:
        return True
    if items[mid] < target:
        return contains(items[mid + 1:], target)
    return contains(items[:mid], target)
print(contains([3, 8, 12, 19, 25], 8))  # True
Base cases: empty list or a hit. Otherwise recurse on the half that can contain the target.

def search(items, target, low, high):
    if low > high:
        return -1
    mid = (low + high) // 2
    if items[mid] == target:
        return mid
    if items[mid] < target:
        return search(items, target, mid + 1, high)
    return search(items, target, low, mid - 1)
print(search([3, 8, 12, 19, 25], 19, 0, 4))  # 3
Each slice copies half the list, which makes the sliced version O(n); passing indexes keeps it O(log n) and returns a position.

