def comparisons(nums):
    count, swapped = 0, True
    while swapped:
        swapped = False
        for i in range(len(nums) - 1):
            count += 1
            if nums[i] > nums[i + 1]:
                nums[i], nums[i + 1] = nums[i + 1], nums[i]
                swapped = True
    return count
print(comparisons(list(range(10, 0, -1))), comparisons(list(range(10))))  # 90 9
Reversed input needs n passes of n - 1 comparisons; sorted input stops after one pass.

