def quick_sort(nums):
    if len(nums) <= 1:
        return nums
    pivot = nums[0]
    smaller = [x for x in nums[1:] if x < pivot]
    larger = [x for x in nums[1:] if x >= pivot]
    return quick_sort(smaller) + [pivot] + quick_sort(larger)
print(quick_sort([7, 2, 9, 4, 1, 7]))  # [1, 2, 4, 7, 7, 9]
Unlike merge sort, the work happens before the recursive calls; joining is just +.

def quick_sort(nums):
    if len(nums) <= 1:
        return nums
    pivot = nums[0]
    smaller = [x for x in nums if x < pivot]
    larger = [x for x in nums if x >= pivot]   # includes the pivot
    return quick_sort(smaller) + [pivot] + quick_sort(larger)
print(quick_sort([3, 1, 2]))  # RecursionError: maximum recursion depth exceeded
larger never gets shorter than nums, so the recursion never reaches the base case. Use nums[1:].

